import unittest

from tonpy.types import CellSlice

from NFTorrent.messages import PetMemoryNftContent


class TestPetMemoryNftContent(unittest.TestCase):

    def test_content(self):
        # NFT Collection Address: EQBOdDO6iszbtbR0YnOz2IHk2eP6cCVKqkl7vRvoEtwa83lU
        # NFT Address: EQB-SkKqWmL5cfdrTPj1APHJcuELIr-nWc4KwfSyJ5YwrxfC
        content_boc = ""  # noqa: E501
        content = PetMemoryNftContent(CellSlice(content_boc))
        self.assertEqual(len(content.data.description), 693)
        self.assertIsNone(content.data.bag_id)
        self.assertEqual(content.data.image, "https://muratov.xyz/petsmem/images/marcus-1.jpg")

        self.assertEqual(content.imm_data.name, 'Marcus')
        self.assertEqual(content.imm_data.breed, 'Nibelung')
        self.assertEqual(round(content.imm_data.geo_point.longitude, 4), 38.9817)
        self.assertEqual(content.imm_data.birth_date, '*')
        self.assertEqual(content.imm_data.death_date, '2024-11-15')

    def test_content_with_bag_id(self):
        # NFT Collection Address: EQBOdDO6iszbtbR0YnOz2IHk2eP6cCVKqkl7vRvoEtwa83lU
        # NFT Address: EQAX3cFnhW2YljjDO6ZW2NNf8dCA2XWpZQEi0h_sh4YGhXMs
        content_boc = "te6cckEBCgEAogABAAEDASICAwQADE1hcmN1cwIiyNjSgCGyN3DNAAAAACAkERUFBgJJ3Snm9YGw1zGQn+hh9MhPe/Rf9XX12p3IOYuKVeWc/YOtOhnc8AcIABBOaWJlbHVuZwAgS3Jhc25vZGFyIDM1MDAyMAAsRGVzY3JpcHRpb24gd2FzIGVkaXRlZAEBoAkAMjo3YjZqbmx5ZHI2c2VlbGlsam50Zndrd3qSPWP4"  # noqa: E501
        content = PetMemoryNftContent(CellSlice(content_boc))
        self.assertEqual(len(content.data.bag_id), 64)
        self.assertEqual(content.data.image, ":7b6jnlydr6seeliljntfwkwz")

    def test_content_with_onchain_image(self):
        # NFT Collection Address: EQBOdDO6iszbtbR0YnOz2IHk2eP6cCVKqkl7vRvoEtwa83lU
        # NFT Address: EQA8EOIZV_3IMC8Ph5-_aN2QHkoR8n5rSzfwmIh8b5Q7OIGU
        content_boc = ""  # noqa: E501
        content = PetMemoryNftContent(CellSlice(content_boc))
        self.assertEqual(len(content.data.image_data), 4851)
